{
  "name": "ReceiptPro",
  "description": "Uma plataforma profissional para geração de comprovantes de compra. Preencha os detalhes, gere PDFs e utilize IA para comunicação com clientes.",
  "requestFramePermissions": []
}

export interface Product {
  code?: string;
  name: string;
  price: number;
  quantity: number;
  warrantyTime?: string;
  warrantyUnit?: 'DIAS' | 'MESES' | 'ANOS';
}

export interface CatalogItem {
  name: string;
  price: number;
}

export interface ReceiptData {
  saleCode: string;
  salesperson: string;
  date: string;
  name: string;
  cpf: string;
  email: string;
  address: {
    street: string;
    number: string;
    neighborhood: string;
    city: string;
    complement: string;
  };
  contact: string;
  paymentMethod: string;
  products: Product[];
  discountValue: number;
  discountType: 'fixed' | 'percentage';
  observation: string;
}

export const INITIAL_DATA: ReceiptData = {
  saleCode: '',
  salesperson: '',
  date: new Date().toISOString().split('T')[0],
  name: '',
  cpf: '',
  email: '',
  address: {
    street: '',
    number: '',
    neighborhood: '',
    city: '',
    complement: '',
  },
  contact: '',
  paymentMethod: 'PIX',
  products: [],
  discountValue: 0,
  discountType: 'fixed',
  observation: '',
};

export const DEFAULT_CATALOG: CatalogItem[] = [
  { name: "PRODUTO EXEMPLO A", price: 100.00 },
  { name: "PRODUTO EXEMPLO B", price: 250.00 },
  { name: "SERVIÇO DE MANUTENÇÃO", price: 150.00 },
];

import { jsPDF } from 'jspdf';
import { ReceiptData } from '../types';
import QRCode from 'qrcode';

const COLORS = {
  primary: '#1e293b',
  secondary: '#64748b',
  accent: '#3b82f6',
  border: '#e2e8f0',
  text: '#1e293b',
  lightText: '#64748b',
  white: '#ffffff',
  bg: '#f8fafc'
};

export const generateReceiptPDF = async (data: ReceiptData) => {
  const doc = new jsPDF();
  const pageWidth = 210;
  const margin = 20;
  const contentWidth = pageWidth - (margin * 2);
  let y = 20;

  // Header
  doc.setFillColor(COLORS.primary);
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(COLORS.white);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(22);
  doc.text("COMPROVANTE DE COMPRA", margin, 25);

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text(`Nº do Pedido: ${data.saleCode || '---'}`, margin, 32);

  y = 55;

  // Client Info Box
  doc.setDrawColor(COLORS.border);
  doc.setFillColor(COLORS.bg);
  doc.roundedRect(margin, y, contentWidth, 35, 2, 2, 'FD');

  doc.setTextColor(COLORS.primary);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(10);
  doc.text("DADOS DO CLIENTE", margin + 5, y + 8);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(9);
  doc.setTextColor(COLORS.text);
  doc.text(`Nome: ${data.name || '---'}`, margin + 5, y + 15);
  doc.text(`CPF/CNPJ: ${data.cpf || '---'}`, margin + 5, y + 20);
  doc.text(`Contato: ${data.contact || '---'}`, margin + 5, y + 25);

  const addressStr = `${data.address.street}, ${data.address.number} - ${data.address.neighborhood}`;
  doc.text(`Endereço: ${addressStr}`, margin + 5, y + 30);

  y += 45;

  // Table Header
  doc.setFillColor(COLORS.primary);
  doc.rect(margin, y, contentWidth, 8, 'F');
  doc.setTextColor(COLORS.white);
  doc.setFont("helvetica", "bold");
  doc.text("DESCRIÇÃO", margin + 5, y + 5.5);
  doc.text("QTD", margin + 110, y + 5.5, { align: 'center' });
  doc.text("UNIT", margin + 140, y + 5.5, { align: 'right' });
  doc.text("TOTAL", margin + contentWidth - 5, y + 5.5, { align: 'right' });

  y += 8;
  doc.setTextColor(COLORS.text);
  doc.setFont("helvetica", "normal");

  let subtotal = 0;
  data.products.forEach((p, i) => {
    const itemTotal = p.price * p.quantity;
    subtotal += itemTotal;

    if (y > 250) {
      doc.addPage();
      y = 20;
    }

    doc.text(p.name.toUpperCase(), margin + 5, y + 6);
    doc.text(p.quantity.toString(), margin + 110, y + 6, { align: 'center' });
    doc.text(p.price.toLocaleString('pt-BR', { minimumFractionDigits: 2 }), margin + 140, y + 6, { align: 'right' });
    doc.text(itemTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 }), margin + contentWidth - 5, y + 6, { align: 'right' });

    doc.setDrawColor(COLORS.border);
    doc.line(margin, y + 9, margin + contentWidth, y + 9);
    y += 10;
  });

  y += 5;

  // Totals
  const totalsX = margin + contentWidth - 60;
  const discount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const total = Math.max(0, subtotal - discount);

  doc.setFont("helvetica", "normal");
  doc.text("Subtotal:", totalsX, y);
  doc.text(subtotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }), margin + contentWidth - 5, y, { align: 'right' });

  y += 6;
  if (discount > 0) {
    doc.text("Desconto:", totalsX, y);
    doc.text(`- ${discount.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}`, margin + contentWidth - 5, y, { align: 'right' });
    y += 6;
  }

  doc.setFont("helvetica", "bold");
  doc.setFontSize(12);
  doc.text("TOTAL:", totalsX, y + 2);
  doc.text(total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }), margin + contentWidth - 5, y + 2, { align: 'right' });

  // QR Code & Footer
  try {
    const qrDataUrl = await QRCode.toDataURL(window.location.href);
    doc.addImage(qrDataUrl, 'PNG', margin, 250, 25, 25);
  } catch (e) {}

  doc.setFontSize(8);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(COLORS.secondary);
  doc.text("Este documento é um comprovante de compra digital.", margin + 30, 260);
  doc.text(`Gerado em ${new Date().toLocaleString('pt-BR')}`, margin + 30, 264);

  doc.save(`Comprovante_${data.name || 'Cliente'}.pdf`);
};

import React, { useState, useEffect, useMemo } from 'react';
import { INITIAL_DATA, ReceiptData, Product, CatalogItem, DEFAULT_CATALOG } from './types';
import { generateReceiptPDF } from './services/pdfService';
import { generateClientMessage, parseReceiptFromText } from './services/geminiService';
import { Input, Select, TextArea } from './components/Input';
import { 
  Plus, Trash2, Search, Download, Send, RefreshCcw, 
  User, MapPin, CreditCard, FileText, Sparkles, Loader2,
  ShoppingCart, Package, Briefcase
} from 'lucide-react';
import Fuse from 'fuse.js';

export default function App() {
  const [data, setData] = useState<ReceiptData>(() => {
    const saved = localStorage.getItem('receipt_pro_data');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [catalog, setCatalog] = useState<CatalogItem[]>(() => {
    const saved = localStorage.getItem('receipt_pro_catalog');
    return saved ? JSON.parse(saved) : DEFAULT_CATALOG;
  });

  const [searchTerm, setSearchTerm] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [importText, setImportText] = useState("");

  useEffect(() => {
    localStorage.setItem('receipt_pro_data', JSON.stringify(data));
  }, [data]);

  useEffect(() => {
    localStorage.setItem('receipt_pro_catalog', JSON.stringify(catalog));
  }, [catalog]);

  const fuse = useMemo(() => new Fuse(catalog, { keys: ['name'], threshold: 0.3 }), [catalog]);
  const searchResults = useMemo(() => searchTerm ? fuse.search(searchTerm).map(r => r.item) : [], [searchTerm, fuse]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    if (name.includes('.')) {
      const [parent, child] = name.split('.');
      setData(prev => ({
        ...prev,
        [parent]: { ...(prev as any)[parent], [child]: value }
      }));
    } else {
      setData(prev => ({ ...prev, [name]: value }));
    }
  };

  const addProduct = (item: CatalogItem) => {
    setData(prev => ({
      ...prev,
      products: [...prev.products, {
        name: item.name,
        price: item.price,
        quantity: 1,
        code: Math.floor(1000 + Math.random() * 9000).toString()
      }]
    }));
    setSearchTerm("");
  };

  const removeProduct = (index: number) => {
    setData(prev => ({
      ...prev,
      products: prev.products.filter((_, i) => i !== index)
    }));
  };

  const updateQuantity = (index: number, delta: number) => {
    setData(prev => ({
      ...prev,
      products: prev.products.map((p, i) => 
        i === index ? { ...p, quantity: Math.max(1, p.quantity + delta) } : p
      )
    }));
  };

  const handleImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    try {
      const result = await parseReceiptFromText(importText, catalog.map(c => c.name));
      if (result.clientData) {
        setData(prev => ({
          ...prev,
          ...result.clientData,
          address: { ...prev.address, ...result.clientData.address }
        }));
      }
      if (result.items) {
        const newProducts = result.items.map((item: any) => {
          const catItem = catalog.find(c => c.name === item.name) || { name: item.name, price: 0 };
          return {
            name: catItem.name,
            price: catItem.price,
            quantity: item.quantity || 1,
            code: Math.floor(1000 + Math.random() * 9000).toString()
          };
        });
        setData(prev => ({ ...prev, products: [...prev.products, ...newProducts] }));
      }
      setImportText("");
    } catch (e) {
      alert("Erro ao processar texto com IA.");
    } finally {
      setIsImporting(false);
    }
  };

  const subtotal = data.products.reduce((acc, p) => acc + (p.price * p.quantity), 0);
  const discount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const total = Math.max(0, subtotal - discount);

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-blue-600 p-1.5 rounded-lg">
              <FileText className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-xl font-bold tracking-tight text-slate-800">ReceiptPro</h1>
          </div>
          <div className="flex items-center gap-3">
            <button 
              onClick={() => setData(INITIAL_DATA)}
              className="p-2 text-slate-500 hover:text-slate-700 hover:bg-slate-100 rounded-lg transition-colors"
              title="Limpar tudo"
            >
              <RefreshCcw className="w-5 h-5" />
            </button>
            <button 
              onClick={() => generateReceiptPDF(data)}
              className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-semibold transition-all shadow-sm"
            >
              <Download className="w-4 h-4" /> Gere PDF
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* Inputs Section */}
          <div className="lg:col-span-7 space-y-6">
            {/* Customer Details */}
            <section className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
              <h2 className="text-sm font-bold text-slate-500 uppercase tracking-wider mb-4 flex items-center gap-2">
                <User className="w-4 h-4" /> Detalhes do Cliente
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <Input label="Nome Completo" name="name" value={data.name} onChange={handleChange} />
                <Input label="CPF ou CNPJ" name="cpf" value={data.cpf} onChange={handleChange} />
                <Input label="E-mail" name="email" value={data.email} onChange={handleChange} />
                <Input label="WhatsApp / Contato" name="contact" value={data.contact} onChange={handleChange} />
              </div>
              <div className="mt-4 grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="md:col-span-2">
                  <Input label="Rua / Logradouro" name="address.street" value={data.address.street} onChange={handleChange} />
                </div>
                <Input label="Número" name="address.number" value={data.address.number} onChange={handleChange} />
                <Input label="Bairro" name="address.neighborhood" value={data.address.neighborhood} onChange={handleChange} />
                <Input label="Cidade" name="address.city" value={data.address.city} onChange={handleChange} />
                <Input label="Complemento" name="address.complement" value={data.address.complement} onChange={handleChange} />
              </div>
            </section>

            {/* Product Selector */}
            <section className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
              <h2 className="text-sm font-bold text-slate-500 uppercase tracking-wider mb-4 flex items-center gap-2">
                <ShoppingCart className="w-4 h-4" /> Itens do Pedido
              </h2>
              <div className="relative mb-6">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                  <Search className="w-4 h-4" />
                </div>
                <input 
                  type="text"
                  placeholder="Buscar no catálogo..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all"
                />
                {searchTerm && searchResults.length > 0 && (
                  <div className="absolute z-20 w-full mt-1 bg-white border border-slate-200 rounded-lg shadow-lg max-h-48 overflow-y-auto">
                    {searchResults.map((item, i) => (
                      <button 
                        key={i}
                        onClick={() => addProduct(item)}
                        className="w-full text-left px-4 py-3 hover:bg-slate-50 flex justify-between items-center transition-colors border-b last:border-0 border-slate-100"
                      >
                        <span className="font-medium text-slate-700">{item.name}</span>
                        <span className="text-blue-600 font-bold">R$ {item.price.toFixed(2)}</span>
                      </button>
                    ))}
                  </div>
                )}
              </div>

              <div className="space-y-3">
                {data.products.map((product, index) => (
                  <div key={index} className="flex items-center gap-4 bg-slate-50 p-3 rounded-lg border border-slate-100 group">
                    <div className="flex-1">
                      <p className="font-bold text-slate-800 text-sm uppercase">{product.name}</p>
                      <p className="text-xs text-slate-500">Unit: R$ {product.price.toFixed(2)}</p>
                    </div>
                    <div className="flex items-center gap-2">
                      <button onClick={() => updateQuantity(index, -1)} className="w-6 h-6 flex items-center justify-center bg-white border border-slate-200 rounded hover:bg-slate-100">-</button>
                      <span className="w-8 text-center font-bold text-sm">{product.quantity}</span>
                      <button onClick={() => updateQuantity(index, 1)} className="w-6 h-6 flex items-center justify-center bg-white border border-slate-200 rounded hover:bg-slate-100">+</button>
                    </div>
                    <div className="text-right w-24">
                      <p className="font-bold text-blue-600 text-sm">R$ {(product.price * product.quantity).toFixed(2)}</p>
                    </div>
                    <button onClick={() => removeProduct(index)} className="p-2 text-slate-300 hover:text-red-500 transition-colors">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                ))}
                {data.products.length === 0 && (
                  <div className="py-8 text-center border-2 border-dashed border-slate-200 rounded-xl text-slate-400">
                    Nenhum item adicionado ao carrinho.
                  </div>
                )}
              </div>
            </section>

            {/* Advanced / IA Section */}
            <section className="bg-slate-800 p-6 rounded-xl text-white shadow-lg overflow-hidden relative">
              <div className="absolute top-0 right-0 p-4 opacity-10">
                <Sparkles className="w-24 h-24" />
              </div>
              <h2 className="text-sm font-bold text-blue-400 uppercase tracking-wider mb-4 flex items-center gap-2">
                <Sparkles className="w-4 h-4" /> Assistente de IA
              </h2>
              <div className="space-y-4">
                <TextArea 
                  label="Importar texto de ficha ou pedido..." 
                  value={importText} 
                  onChange={(e) => setImportText(e.target.value)} 
                  className="bg-slate-900 border-slate-700 text-white h-24 placeholder:text-slate-600"
                />
                <button 
                  onClick={handleImport}
                  disabled={isImporting}
                  className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-slate-600 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all"
                >
                  {isImporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                  Processar com Inteligência Artificial
                </button>
              </div>
            </section>
          </div>

          {/* Sidebar Summary */}
          <div className="lg:col-span-5 space-y-6">
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm sticky top-24">
              <h2 className="text-sm font-bold text-slate-500 uppercase tracking-wider mb-6">Resumo Financeiro</h2>

              <div className="space-y-4 mb-8">
                <div className="flex justify-between items-center text-slate-600">
                  <span>Subtotal</span>
                  <span className="font-semibold">R$ {subtotal.toFixed(2)}</span>
                </div>

                <div className="space-y-2">
                  <div className="flex gap-2">
                    <Select 
                      label="Tipo" 
                      name="discountType" 
                      value={data.discountType} 
                      onChange={handleChange} 
                      options={['fixed', 'percentage']}
                      className="w-1/3"
                    />
                    <Input 
                      label="Valor Desconto" 
                      name="discountValue" 
                      type="number"
                      value={data.discountValue} 
                      onChange={handleChange} 
                      className="flex-1"
                    />
                  </div>
                </div>

                <div className="pt-4 border-t border-slate-100">
                  <div className="flex justify-between items-center">
                    <span className="text-lg font-bold text-slate-800">Total</span>
                    <span className="text-2xl font-black text-blue-600">R$ {total.toFixed(2)}</span>
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <Input label="Código do Pedido" name="saleCode" value={data.saleCode} onChange={handleChange} />
                <Select 
                  label="Método de Pagamento" 
                  name="paymentMethod" 
                  value={data.paymentMethod} 
                  onChange={handleChange} 
                  options={['PIX', 'CARTÃO CRÉDITO', 'CARTÃO DÉBITO', 'DINHEIRO', 'BOLETO']} 
                />
                <Input label="Nome do Vendedor" name="salesperson" value={data.salesperson} onChange={handleChange} />
              </div>

              <div className="mt-8 grid grid-cols-2 gap-3">
                <button 
                  onClick={async () => {
                    const msg = await generateClientMessage(data);
                    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
                  }}
                  className="flex items-center justify-center gap-2 bg-green-600 hover:bg-green-700 text-white font-bold py-3 rounded-lg transition-all"
                >
                  <Send className="w-4 h-4" /> WhatsApp
                </button>
                <button 
                  onClick={() => generateReceiptPDF(data)}
                  className="flex items-center justify-center gap-2 bg-slate-800 hover:bg-slate-900 text-white font-bold py-3 rounded-lg transition-all"
                >
                  <Download className="w-4 h-4" /> PDF
                </button>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

import { GoogleGenAI, Type } from "@google/genai";
import { ReceiptData } from "../types";

export const generateClientMessage = async (data: ReceiptData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const subtotal = data.products.reduce((acc, p) => acc + (p.price * p.quantity), 0);
  const discount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const total = Math.max(0, subtotal - discount);

  const prompt = `
    Você é um assistente de vendas profissional. 
    Escreva uma mensagem amigável para enviar ao cliente via WhatsApp confirmando o pedido.

    Dados:
    Cliente: ${data.name}
    Total: ${total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
    Itens: ${data.products.map(p => `${p.quantity}x ${p.name}`).join(', ')}
    Pagamento: ${data.paymentMethod}
    Pedido: ${data.saleCode}

    Seja conciso e use emojis de forma moderada.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    });
    return response.text || "Olá, seu pedido foi confirmado!";
  } catch (error) {
    return "Olá, seu pedido foi confirmado com sucesso!";
  }
};

export const parseReceiptFromText = async (text: string, catalogNames: string[] = []): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Extraia informações de pedido do texto abaixo e retorne em JSON.
    Tente mapear os nomes dos produtos para os itens do catálogo se houver semelhança.

    Catálogo disponível: ${catalogNames.join(', ')}

    Texto: ${text}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            clientData: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                cpf: { type: Type.STRING },
                contact: { type: Type.STRING },
                email: { type: Type.STRING },
                address: {
                  type: Type.OBJECT,
                  properties: {
                    street: { type: Type.STRING },
                    number: { type: Type.STRING },
                    neighborhood: { type: Type.STRING },
                    city: { type: Type.STRING }
                  }
                }
              }
            },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  quantity: { type: Type.NUMBER }
                }
              }
            }
          }
        }
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    throw error;
  }
};

import path from 'path';
import { fileURLToPath } from 'url';
import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';

// Fix: __dirname is not defined in ESM (ECMAScript Modules) environments.
// We derive it from import.meta.url using fileURLToPath.
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export default defineConfig(({ mode }) => {
    const env = loadEnv(mode, '.', '');
    return {
      server: {
        port: 3000,
        host: '0.0.0.0',
      },
      plugins: [react()],
      define: {
        'process.env.API_KEY': JSON.stringify(env.GEMINI_API_KEY),
        'process.env.GEMINI_API_KEY': JSON.stringify(env.GEMINI_API_KEY)
      },
      resolve: {
        alias: {
          '@': path.resolve(__dirname, '.'),
        }
      }
    };
});

