export const DEFAULT_CATALOG: CatalogItem[] = [
  { name: "COLCHÃO BELCONFORT PREMIUM QUEEN", price: 4500.00 },
  { name: "COLCHÃO BELCONFORT LUXURY KING", price: 6200.00 },
  { name: "BASE BOX BELCONFORT REVESTIDA", price: 1200.00 },
  { name: "TRAVESSEIRO BELCONFORT CLOUD", price: 250.00 },
  { name: "PROTETOR DE COLCHÃO IMPERMEÁVEL", price: 180.00 },
];

import React, { useState, useEffect, useMemo } from 'react';
import { INITIAL_DATA, ReceiptData, Product, CatalogItem, DEFAULT_CATALOG } from './types';
import { generateReceiptPDF } from './services/pdfService';
import { generateClientMessage, parseReceiptFromText } from './services/geminiService';
import { Input, Select, TextArea } from './components/Input';
import { 
  Plus, Trash2, Search, Download, Send, RefreshCcw, 
  User, MapPin, CreditCard, FileText, Sparkles, Loader2,
  ShoppingCart, ShieldCheck, Crown
} from 'lucide-react';
import Fuse from 'fuse.js';

export default function App() {
  const [data, setData] = useState<ReceiptData>(() => {
    const saved = localStorage.getItem('belconfort_data');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [catalog, setCatalog] = useState<CatalogItem[]>(() => {
    const saved = localStorage.getItem('belconfort_catalog');
    return saved ? JSON.parse(saved) : DEFAULT_CATALOG;
  });

  const [searchTerm, setSearchTerm] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [importText, setImportText] = useState("");

  useEffect(() => {
    localStorage.setItem('belconfort_data', JSON.stringify(data));
  }, [data]);

  useEffect(() => {
    localStorage.setItem('belconfort_catalog', JSON.stringify(catalog));
  }, [catalog]);

  const fuse = useMemo(() => new Fuse(catalog, { keys: ['name'], threshold: 0.3 }), [catalog]);
  const searchResults = useMemo(() => searchTerm ? fuse.search(searchTerm).map(r => r.item) : [], [searchTerm, fuse]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    if (name.includes('.')) {
      const [parent, child] = name.split('.');
      setData(prev => ({
        ...prev,
        [parent]: { ...(prev as any)[parent], [child]: value }
      }));
    } else {
      setData(prev => ({ ...prev, [name]: value }));
    }
  };

  const addProduct = (item: CatalogItem) => {
    setData(prev => ({
      ...prev,
      products: [...prev.products, {
        name: item.name,
        price: item.price,
        quantity: 1,
        code: Math.floor(1000 + Math.random() * 9000).toString()
      }]
    }));
    setSearchTerm("");
  };

  const removeProduct = (index: number) => {
    setData(prev => ({
      ...prev,
      products: prev.products.filter((_, i) => i !== index)
    }));
  };

  const updateQuantity = (index: number, delta: number) => {
    setData(prev => ({
      ...prev,
      products: prev.products.map((p, i) => 
        i === index ? { ...p, quantity: Math.max(1, p.quantity + delta) } : p
      )
    }));
  };

  const handleImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    try {
      const result = await parseReceiptFromText(importText, catalog.map(c => c.name));
      if (result.clientData) {
        setData(prev => ({
          ...prev,
          ...result.clientData,
          address: { ...prev.address, ...result.clientData.address }
        }));
      }
      if (result.items) {
        const newProducts = result.items.map((item: any) => {
          const catItem = catalog.find(c => c.name === item.name) || { name: item.name, price: 0 };
          return {
            name: catItem.name,
            price: catItem.price,
            quantity: item.quantity || 1,
            code: Math.floor(1000 + Math.random() * 9000).toString()
          };
        });
        setData(prev => ({ ...prev, products: [...prev.products, ...newProducts] }));
      }
      setImportText("");
    } catch (e) {
      alert("Erro ao processar dados via IA.");
    } finally {
      setIsImporting(false);
    }
  };

  const subtotal = data.products.reduce((acc, p) => acc + (p.price * p.quantity), 0);
  const discount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const total = Math.max(0, subtotal - discount);

  return (
    <div className="min-h-screen bg-[#0d1117] text-gray-100 font-sans pb-12">
      <header className="bg-gray-900/80 backdrop-blur-md border-b border-gray-800 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-700 p-2 rounded-xl shadow-lg shadow-blue-900/20">
              <Crown className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-2xl font-serif font-bold tracking-tight text-white">BELCONFORT</h1>
              <p className="text-[10px] text-blue-400 font-bold uppercase tracking-[0.2em]">Ecosystem Premium</p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button 
              onClick={() => setData(INITIAL_DATA)}
              className="p-2.5 text-gray-400 hover:text-white hover:bg-gray-800 rounded-xl transition-all"
              title="Reiniciar Formulário"
            >
              <RefreshCcw className="w-5 h-5" />
            </button>
            <button 
              onClick={() => generateReceiptPDF(data)}
              className="flex items-center gap-2 bg-blue-700 hover:bg-blue-600 text-white px-6 py-2.5 rounded-xl font-bold transition-all shadow-lg shadow-blue-900/30"
            >
              <Download className="w-5 h-5" /> GERAR COMPROVANTE
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* Main Content Area */}
          <div className="lg:col-span-7 space-y-8">
            {/* Customer Information */}
            <section className="bg-gray-900 border border-gray-800 rounded-2xl p-8 shadow-xl">
              <div className="flex items-center gap-3 mb-8">
                <div className="w-1.5 h-6 bg-blue-600 rounded-full"></div>
                <h2 className="text-xl font-serif font-bold text-white uppercase tracking-wide">Ficha do Cliente</h2>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <Input label="Nome Completo" name="name" value={data.name} onChange={handleChange} icon={<User className="w-4 h-4"/>} />
                <Input label="CPF ou CNPJ" name="cpf" value={data.cpf} onChange={handleChange} icon={<ShieldCheck className="w-4 h-4"/>} />
                <Input label="WhatsApp / Telefone" name="contact" value={data.contact} onChange={handleChange} icon={<Send className="w-4 h-4"/>} />
                <Input label="E-mail" name="email" value={data.email} onChange={handleChange} />
              </div>
              <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="md:col-span-2">
                  <Input label="Rua / Avenida" name="address.street" value={data.address.street} onChange={handleChange} icon={<MapPin className="w-4 h-4"/>} />
                </div>
                <Input label="Número" name="address.number" value={data.address.number} onChange={handleChange} />
                <Input label="Bairro" name="address.neighborhood" value={data.address.neighborhood} onChange={handleChange} />
                <Input label="Cidade" name="address.city" value={data.address.city} onChange={handleChange} />
                <Input label="Complemento" name="address.complement" value={data.address.complement} onChange={handleChange} />
              </div>
            </section>

            {/* Catalog & Cart */}
            <section className="bg-gray-900 border border-gray-800 rounded-2xl p-8 shadow-xl">
              <div className="flex items-center gap-3 mb-8">
                <div className="w-1.5 h-6 bg-blue-600 rounded-full"></div>
                <h2 className="text-xl font-serif font-bold text-white uppercase tracking-wide">Catálogo de Itens</h2>
              </div>

              <div className="relative mb-8">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-gray-500">
                  <Search className="w-5 h-5" />
                </div>
                <input 
                  type="text"
                  placeholder="BUSCAR PRODUTO NO CATÁLOGO..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pl-12 pr-4 py-4 bg-gray-800 border-2 border-gray-700 rounded-xl focus:ring-4 focus:ring-blue-600/20 focus:border-blue-600 transition-all text-sm uppercase tracking-widest font-bold"
                />
                {searchTerm && searchResults.length > 0 && (
                  <div className="absolute z-40 w-full mt-2 bg-gray-800 border border-gray-700 rounded-xl shadow-2xl max-h-60 overflow-y-auto overflow-x-hidden">
                    {searchResults.map((item, i) => (
                      <button 
                        key={i}
                        onClick={() => addProduct(item)}
                        className="w-full text-left px-6 py-4 hover:bg-gray-750 flex justify-between items-center transition-colors border-b border-gray-700 last:border-0"
                      >
                        <span className="font-bold text-gray-100 uppercase text-xs">{item.name}</span>
                        <span className="text-blue-500 font-black">R$ {item.price.toFixed(2)}</span>
                      </button>
                    ))}
                  </div>
                )}
              </div>

              <div className="space-y-4">
                {data.products.map((product, index) => (
                  <div key={index} className="flex items-center gap-6 bg-gray-800/50 p-5 rounded-2xl border border-gray-700/50 group transition-all hover:bg-gray-800 hover:border-gray-600">
                    <div className="flex-1">
                      <p className="font-black text-white text-xs tracking-widest uppercase mb-1">{product.name}</p>
                      <p className="text-[10px] text-gray-400 font-bold">VALOR UNITÁRIO: R$ {product.price.toFixed(2)}</p>
                    </div>
                    <div className="flex items-center bg-gray-900 rounded-lg border border-gray-700 px-2">
                      <button onClick={() => updateQuantity(index, -1)} className="w-8 h-10 flex items-center justify-center text-gray-400 hover:text-white">-</button>
                      <span className="w-8 text-center font-black text-sm text-blue-500">{product.quantity}</span>
                      <button onClick={() => updateQuantity(index, 1)} className="w-8 h-10 flex items-center justify-center text-gray-400 hover:text-white">+</button>
                    </div>
                    <div className="text-right min-w-[120px]">
                      <p className="font-black text-white text-sm">R$ {(product.price * product.quantity).toFixed(2)}</p>
                    </div>
                    <button onClick={() => removeProduct(index)} className="p-2 text-gray-600 hover:text-red-500 transition-colors">
                      <Trash2 className="w-5 h-5" />
                    </button>
                  </div>
                ))}
                {data.products.length === 0 && (
                  <div className="py-12 text-center border-2 border-dashed border-gray-800 rounded-2xl">
                    <ShoppingCart className="w-12 h-12 text-gray-800 mx-auto mb-4" />
                    <p className="text-gray-600 font-bold uppercase tracking-widest text-xs">Nenhum item selecionado</p>
                  </div>
                )}
              </div>
            </section>
          </div>

          {/* Sticky Sidebar */}
          <div className="lg:col-span-5 space-y-8">
            <div className="bg-gray-900 border border-gray-800 rounded-2xl p-8 shadow-xl sticky top-28">
              <h2 className="text-sm font-black text-blue-500 uppercase tracking-[0.3em] mb-8 text-center">Checkout Detalhado</h2>

              <div className="space-y-5 mb-8">
                <div className="flex justify-between items-center text-gray-400 font-bold text-xs uppercase tracking-widest">
                  <span>Subtotal Bruto</span>
                  <span className="text-gray-200">R$ {subtotal.toFixed(2)}</span>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <Select 
                    label="Desconto" 
                    name="discountType" 
                    value={data.discountType} 
                    onChange={handleChange} 
                    options={['fixed', 'percentage']}
                  />
                  <Input 
                    label="Valor" 
                    name="discountValue" 
                    type="number"
                    value={data.discountValue} 
                    onChange={handleChange} 
                  />
                </div>

                <div className="pt-6 border-t border-gray-800 mt-6">
                  <div className="flex flex-col items-center">
                    <span className="text-[10px] font-black text-gray-500 uppercase tracking-[0.2em] mb-2">Total a Pagar</span>
                    <span className="text-4xl font-serif font-bold text-white">R$ {total.toFixed(2)}</span>
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <Input label="Código do Pedido" name="saleCode" value={data.saleCode} onChange={handleChange} />
                <Select 
                  label="Forma de Pagamento" 
                  name="paymentMethod" 
                  value={data.paymentMethod} 
                  onChange={handleChange} 
                  options={['PIX', 'CARTÃO DE CRÉDITO', 'CARTÃO DE DÉBITO', 'DINHEIRO', 'BOLETO']} 
                  icon={<CreditCard className="w-4 h-4"/>}
                />
                <Input label="Assinatura Vendedor" name="salesperson" value={data.salesperson} onChange={handleChange} />
              </div>

              <div className="mt-10 grid grid-cols-1 gap-4">
                <button 
                  onClick={async () => {
                    const msg = await generateClientMessage(data);
                    window.open(`https://wa.me/${data.contact.replace(/\D/g,'')}?text=${encodeURIComponent(msg)}`, '_blank');
                  }}
                  className="w-full flex items-center justify-center gap-3 bg-[#25D366] hover:bg-[#20ba59] text-white font-black py-4 rounded-xl transition-all shadow-lg text-xs tracking-widest uppercase"
                >
                  <Send className="w-5 h-5" /> Enviar p/ Cliente
                </button>
                <button 
                  onClick={() => generateReceiptPDF(data)}
                  className="w-full flex items-center justify-center gap-3 bg-blue-700 hover:bg-blue-600 text-white font-black py-4 rounded-xl transition-all shadow-lg text-xs tracking-widest uppercase"
                >
                  <Download className="w-5 h-5" /> Baixar Comprovante PDF
                </button>
              </div>
            </div>

            {/* AI Assistant Section */}
            <div className="bg-gradient-to-br from-gray-900 to-blue-900/20 border border-blue-900/30 rounded-2xl p-8 shadow-2xl relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-6 opacity-5 group-hover:opacity-10 transition-opacity">
                <Sparkles className="w-32 h-32 text-blue-400" />
              </div>
              <h3 className="text-blue-400 font-black text-xs uppercase tracking-[0.3em] mb-6 flex items-center gap-2">
                <Sparkles className="w-4 h-4" /> Importação Inteligente
              </h3>
              <TextArea 
                label="Cole aqui o texto do pedido ou dados do cliente para preencher automaticamente..." 
                value={importText} 
                onChange={(e) => setImportText(e.target.value)}
                className="bg-gray-950/50 border-gray-800 text-xs font-medium placeholder:text-gray-700 h-28"
              />
              <button 
                onClick={handleImport}
                disabled={isImporting}
                className="w-full mt-4 bg-white hover:bg-gray-100 disabled:bg-gray-800 disabled:text-gray-600 text-gray-950 font-black py-3 rounded-xl flex items-center justify-center gap-2 transition-all uppercase text-[10px] tracking-widest"
              >
                {isImporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
                Extrair Dados com IA
              </button>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

import { jsPDF } from 'jspdf';
import { ReceiptData } from '../types';
import QRCode from 'qrcode';

const COLORS = {
  primary: '#1e40af', // Bel-blue
  secondary: '#1e293b',
  accent: '#3b82f6',
  border: '#cbd5e1',
  text: '#0f172a',
  lightText: '#64748b',
  white: '#ffffff',
  bg: '#f8fafc'
};

export const generateReceiptPDF = async (data: ReceiptData) => {
  const doc = new jsPDF();
  const pageWidth = 210;
  const margin = 20;
  const contentWidth = pageWidth - (margin * 2);
  let y = 20;

  // Header Banner
  doc.setFillColor(COLORS.primary);
  doc.rect(0, 0, pageWidth, 50, 'F');

  doc.setTextColor(COLORS.white);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(28);
  doc.text("BELCONFORT", margin, 30);

  doc.setFontSize(9);
  doc.setFont("helvetica", "normal");
  doc.text("ECOSISTEMA PREMIUM DE CONFORTO", margin, 36);

  doc.setFontSize(14);
  doc.setFont("helvetica", "bold");
  doc.text("COMPROVANTE DE PEDIDO", margin + contentWidth, 32, { align: 'right' });

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text(`CÓDIGO: ${data.saleCode || '---'}`, margin + contentWidth, 38, { align: 'right' });

  y = 65;

  // Customer Section
  doc.setDrawColor(COLORS.primary);
  doc.setLineWidth(0.5);
  doc.line(margin, y, margin + 40, y);

  y += 6;
  doc.setTextColor(COLORS.primary);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(10);
  doc.text("DADOS DO CLIENTE", margin, y);

  y += 8;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(9);
  doc.setTextColor(COLORS.text);
  doc.text(`NOME: ${data.name.toUpperCase() || '---'}`, margin, y);
  doc.text(`CPF/CNPJ: ${data.cpf || '---'}`, margin + 100, y);

  y += 6;
  doc.text(`CONTATO: ${data.contact || '---'}`, margin, y);
  doc.text(`E-MAIL: ${data.email.toLowerCase() || '---'}`, margin + 100, y);

  y += 6;
  const addressStr = `${data.address.street}, ${data.address.number} - ${data.address.neighborhood}, ${data.address.city}`;
  doc.text(`ENDEREÇO: ${addressStr.toUpperCase()}`, margin, y);

  y += 15;

  // Items Table Header
  doc.setFillColor(COLORS.secondary);
  doc.rect(margin, y, contentWidth, 10, 'F');
  doc.setTextColor(COLORS.white);
  doc.setFont("helvetica", "bold");
  doc.text("DESCRIÇÃO DO PRODUTO", margin + 5, y + 6.5);
  doc.text("QTD", margin + 110, y + 6.5, { align: 'center' });
  doc.text("UNITARIO", margin + 140, y + 6.5, { align: 'right' });
  doc.text("TOTAL", margin + contentWidth - 5, y + 6.5, { align: 'right' });

  y += 10;
  doc.setTextColor(COLORS.text);
  doc.setFont("helvetica", "normal");

  let subtotal = 0;
  data.products.forEach((p, i) => {
    const itemTotal = p.price * p.quantity;
    subtotal += itemTotal;

    if (y > 240) {
      doc.addPage();
      y = 20;
    }

    doc.text(p.name.toUpperCase(), margin + 5, y + 7);
    doc.text(p.quantity.toString(), margin + 110, y + 7, { align: 'center' });
    doc.text(p.price.toLocaleString('pt-BR', { minimumFractionDigits: 2 }), margin + 140, y + 7, { align: 'right' });
    doc.text(itemTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 }), margin + contentWidth - 5, y + 7, { align: 'right' });

    doc.setDrawColor(COLORS.border);
    doc.setLineWidth(0.1);
    doc.line(margin, y + 10, margin + contentWidth, y + 10);
    y += 12;
  });

  y += 10;

  // Financial Summary
  const totalsX = margin + contentWidth - 60;
  const discount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const total = Math.max(0, subtotal - discount);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.text("SUBTOTAL:", totalsX, y);
  doc.text(`R$ ${subtotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`, margin + contentWidth - 5, y, { align: 'right' });

  y += 6;
  if (discount > 0) {
    doc.text(`DESCONTO (${data.discountType === 'percentage' ? data.discountValue + '%' : 'FIXO'}):`, totalsX, y);
    doc.text(`- R$ ${discount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`, margin + contentWidth - 5, y, { align: 'right' });
    y += 6;
  }

  y += 4;
  doc.setFillColor(COLORS.primary);
  doc.rect(totalsX - 5, y - 1, 65, 12, 'F');
  doc.setTextColor(COLORS.white);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(12);
  doc.text("TOTAL GERAL:", totalsX, y + 7);
  doc.text(`R$ ${total.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`, margin + contentWidth - 5, y + 7, { align: 'right' });

  // Payment info
  y += 25;
  doc.setTextColor(COLORS.secondary);
  doc.setFontSize(9);
  doc.setFont("helvetica", "bold");
  doc.text("MÉTODO DE PAGAMENTO:", margin, y);
  doc.setFont("helvetica", "normal");
  doc.text(data.paymentMethod.toUpperCase(), margin + 50, y);

  y += 6;
  doc.setFont("helvetica", "bold");
  doc.text("VENDEDOR RESPONSÁVEL:", margin, y);
  doc.setFont("helvetica", "normal");
  doc.text(data.salesperson.toUpperCase() || "ADMINISTRAÇÃO BELCONFORT", margin + 50, y);

  // Footer & QR
  try {
    const qrDataUrl = await QRCode.toDataURL(`https://belconfort.com.br/check/${data.saleCode}`);
    doc.addImage(qrDataUrl, 'PNG', margin, 260, 25, 25);
  } catch (e) {}

  doc.setFontSize(7);
  doc.setTextColor(COLORS.lightText);
  doc.text("ESTE DOCUMENTO É UM COMPROVANTE DIGITAL DE OPERAÇÃO COMERCIAL.", margin + 30, 270);
  doc.text(`BELCONFORT ECOSISTEMA - GERADO EM ${new Date().toLocaleString('pt-BR')}`, margin + 30, 274);
  doc.text("WWW.BELCONFORT.COM.BR", margin + 30, 278);

  doc.save(`BELCONFORT_${data.saleCode || 'PEDIDO'}_${data.name.replace(/\s+/g, '_')}.pdf`);
};

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_DATA, ReceiptData, PRODUCTS_LIST, PRODUCT_CATALOG, Product } from './types';
import { generateReceiptPDF, getReceiptBlob } from './services/pdfService';
import { generateClientMessage, parseReceiptFromText } from './services/geminiService';
import { Input, Select, TextArea } from './components/Input';
import { 
  Calendar, User, MapPin, Hash, Map, Building2, 
  Phone, Download, Printer, CreditCard, Plus, Trash2, Tag, Percent, Search,
  ShieldCheck, Mail, MessageCircle, FileText, Sparkles, Loader2, Barcode,
  Users, UserPlus, ExternalLink, Share2, Copy, RotateCcw, AlertTriangle
} from 'lucide-react';
import Fuse from 'fuse.js';
import JsBarcode from 'jsbarcode';

const STORAGE_KEY = 'belconfort_receipt_data';
const TEAM_STORAGE_KEY = 'belconfort_team_list';

const fuse = new Fuse(PRODUCTS_LIST, {
  includeScore: true,
  threshold: 0.4,
  ignoreLocation: true,
});

const BarcodePreview = ({ code }: { code: string }) => {
  const imgRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    if (imgRef.current && code) {
      try {
        const canvas = document.createElement('canvas');
        JsBarcode(canvas, code, {
          format: "CODE128",
          width: 1,
          height: 30,
          displayValue: false,
          margin: 0,
          background: 'transparent',
          lineColor: '#000000'
        });
        imgRef.current.src = canvas.toDataURL();
      } catch(e) { /* ignore */ }
    }
  }, [code]);

  if (!code) return null;
  return <img ref={imgRef} alt="barcode" className="h-2.5 w-auto max-w-full object-contain opacity-80 mix-blend-multiply mt-0.5" />;
}

export default function App() {
  const [data, setData] = useState<ReceiptData>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        return { ...INITIAL_DATA, ...JSON.parse(savedData) };
      }
    } catch (error) {}
    return INITIAL_DATA;
  });

  const [salespeople, setSalespeople] = useState<string[]>(() => {
    try {
      const savedTeam = localStorage.getItem(TEAM_STORAGE_KEY);
      if (savedTeam) return JSON.parse(savedTeam);
    } catch (error) {}
    return ['ROBSON', 'SARA'];
  });

  const [newSalespersonName, setNewSalespersonName] = useState("");
  const [activeTab, setActiveTab] = useState<'manual' | 'import' | 'team'>('manual');
  const [importText, setImportText] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [importError, setImportError] = useState<{title: string, msg: string} | null>(null);
  const [selectedProduct, setSelectedProduct] = useState("");
  const [selectedPrice, setSelectedPrice] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState("1");
  const [searchTerm, setSearchTerm] = useState("");
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [discountInput, setDiscountInput] = useState("");

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  }, [data]);

  useEffect(() => {
    localStorage.setItem(TEAM_STORAGE_KEY, JSON.stringify(salespeople));
  }, [salespeople]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setData(prev => ({ ...prev, [name]: value }));
  };

  const handleResetData = () => {
    if (window.confirm("Tem certeza que deseja iniciar um novo atendimento?")) {
        setData(INITIAL_DATA);
        setSearchTerm("");
        setDiscountInput("");
        setSelectedProduct("");
        setSelectedPrice("");
        setSelectedQuantity("1");
        setImportText("");
        setImportError(null);
        setActiveTab('manual');
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleAddSalesperson = () => {
    if (newSalespersonName.trim()) {
      const name = newSalespersonName.trim().toUpperCase();
      if (!salespeople.includes(name)) setSalespeople([...salespeople, name]);
      setNewSalespersonName("");
    }
  };

  const handleRemoveSalesperson = (name: string) => {
    setSalespeople(salespeople.filter(s => s !== name));
  };

  const filteredProducts = searchTerm
    ? fuse.search(searchTerm).map(result => result.item)
    : PRODUCTS_LIST;

  const handleSearchSelect = (name: string) => {
    setSelectedProduct(name);
    setSearchTerm(name);
    setIsSearchOpen(false);
    const product = PRODUCT_CATALOG.find(p => p.name === name);
    if (product) setSelectedPrice(product.price.toFixed(2).replace('.', ','));
  };

  const handleAddProduct = () => {
    if (!selectedProduct) return;
    const priceValue = parseFloat(selectedPrice.replace('.', '').replace(',', '.') || "0");
    const quantityValue = parseInt(selectedQuantity) || 1;
    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();
    const newProduct: Product = {
      code: pseudoCode,
      name: selectedProduct,
      price: priceValue,
      quantity: quantityValue,
      warrantyTime: "",
      warrantyUnit: "MESES"
    };
    setData(prev => ({ ...prev, products: [...prev.products, newProduct] }));
    setSelectedProduct("");
    setSearchTerm("");
    setSelectedPrice("");
    setSelectedQuantity("1");
  };

  const handleRemoveProduct = (index: number) => {
    setData(prev => ({ ...prev, products: prev.products.filter((_, i) => i !== index) }));
  };

  const handleUpdateProductWarranty = (index: number, field: 'time' | 'unit', value: string) => {
    setData(prev => ({
      ...prev,
      products: prev.products.map((p, i) => 
        i === index ? { ...p, [field === 'time' ? 'warrantyTime' : 'warrantyUnit']: value } : p
      )
    }));
  };

  const handleDiscountInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setDiscountInput(val);
    const num = parseFloat(val.replace('.', '').replace(',', '.') || "0");
    setData(prev => ({ ...prev, discountValue: num }));
  };

  const handleDiscountTypeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setData(prev => ({ ...prev, discountType: e.target.value as 'fixed' | 'percentage' }));
  };

  const handleSmartImport = async () => {
    if (!importText.trim()) return;
    setIsImporting(true);
    setImportError(null);
    try {
      const result = await parseReceiptFromText(importText, PRODUCTS_LIST);
      let updatedProducts = [...data.products];
      if (result.items) {
        result.items.forEach((item: { name: string, quantity: number }) => {
            const systemProduct = PRODUCT_CATALOG.find(p => p.name === item.name);
            if (systemProduct) {
                const quantityToAdd = item.quantity || 1;
                const existingProductIndex = updatedProducts.findIndex(p => p.name === systemProduct.name);
                if (existingProductIndex >= 0) {
                    updatedProducts[existingProductIndex].quantity += quantityToAdd;
                } else {
                    const pseudoCode = Math.floor(100000 + Math.random() * 900000).toString();
                    updatedProducts.push({
                        code: pseudoCode,
                        name: systemProduct.name,
                        price: systemProduct.price,
                        quantity: quantityToAdd,
                        warrantyTime: "",
                        warrantyUnit: "MESES"
                    });
                }
            }
        });
      }
      setData(prev => ({ ...prev, ...result.clientData, products: updatedProducts }));
      setImportText("");
      setActiveTab('manual');
    } catch (error: any) {
      setImportError({ title: "Erro na IA", msg: error.message });
    } finally {
      setIsImporting(false);
    }
  };

  const getBundleDetails = (products: Product[]) => {
    let totalDiscount = 0;
    let hasBaseDiscount = false;
    let hasPillowDiscount = false;
    const specificPillowName = "TRAVESSEIRO FLOCOS CONFORTO 20CM 60X40 BRANCO";
    const hasAnyOtherProduct = products.some(p => p.name !== specificPillowName);
    let casalMattressCount = 0, queenMattressCount = 0, superKingMattressCount = 0;

    products.forEach(p => {
        const name = p.name.toUpperCase();
        if (name.includes("COLCHÃO") || name.includes("COLCHAO")) {
            if (name.includes("CASAL")) casalMattressCount += p.quantity;
            else if (name.includes("QUEEN")) queenMattressCount += p.quantity;
            else if (name.includes("SUPER KING")) superKingMattressCount += p.quantity;
        }
    });

    products.forEach(p => {
        const name = p.name.toUpperCase();
        if (name === specificPillowName && hasAnyOtherProduct) {
            totalDiscount += (p.price * p.quantity);
            hasPillowDiscount = true;
        }
        if (name.startsWith("BASE")) {
            let targetPrice = 0;
            if (name.includes("CASAL") && casalMattressCount > 0) targetPrice = 250;
            else if (name.includes("QUEEN") && queenMattressCount > 0) targetPrice = 300;
            else if (name.includes("SUPER KING") && superKingMattressCount > 0) targetPrice = 350;

            if (targetPrice > 0) {
              const discountPerItem = Math.max(0, p.price - targetPrice);
              totalDiscount += (discountPerItem * p.quantity);
              hasBaseDiscount = true;
            }
        }
    });

    let label = hasBaseDiscount && hasPillowDiscount ? "Combo + Brinde" : hasBaseDiscount ? "Desconto Combo" : hasPillowDiscount ? "Brinde Travesseiro" : "Desconto Promocional";
    return { totalDiscount, label };
  };

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const bundleDetails = getBundleDetails(data.products);
  const bundleDiscount = bundleDetails.totalDiscount;
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const totalValue = Math.max(0, subtotal - bundleDiscount - manualDiscount);

  const getDataForExport = () => ({
    ...data,
    bundleDiscount,
    bundleLabel: bundleDetails.label
  } as ReceiptData);

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans selection:bg-blue-500 selection:text-white pb-20">
      <header className="border-b border-gray-800 bg-[#0047AB] shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex flex-col">
            <h1 className="text-3xl font-serif font-bold tracking-tight text-white drop-shadow-md">BelConfort</h1>
            <span className="text-blue-100 text-[10px] tracking-[0.2em] font-medium uppercase mt-[-4px]">Camas e Móveis</span>
          </div>
          <div className="flex items-center gap-4">
             <span className="text-[10px] font-medium px-2 py-1 bg-white/10 rounded-full text-white border border-white/20">v1.6.0</span>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-5 space-y-6">
            <div className="flex p-1 space-x-1 bg-gray-900 rounded-xl border border-gray-800">
                <button onClick={() => setActiveTab('manual')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium rounded-lg transition-all ${activeTab === 'manual' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}><FileText className="w-4 h-4" />Manual</button>
                <button onClick={() => setActiveTab('import')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium rounded-lg transition-all ${activeTab === 'import' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}><Sparkles className="w-4 h-4" />Importar</button>
                <button onClick={() => setActiveTab('team')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium rounded-lg transition-all ${activeTab === 'team' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}><Users className="w-4 h-4" />Equipe</button>
            </div>

            {activeTab === 'import' && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                 <h2 className="text-lg font-semibold text-white flex items-center gap-2 mb-4"><span className="w-1 h-6 bg-purple-500 rounded-full"></span>Importação IA</h2>
                 {importError && <div className="mb-4 bg-red-900/20 border border-red-500/50 text-red-200 p-4 rounded-lg text-sm flex gap-3"><AlertTriangle className="w-5 h-5 text-red-400" />{importError.msg}</div>}
                 <TextArea label="Cole os dados aqui..." value={importText} onChange={(e) => setImportText(e.target.value)} className="min-h-[200px] mb-4" />
                 <button onClick={handleSmartImport} disabled={isImporting || !importText.trim()} className="w-full bg-purple-600 hover:bg-purple-700 text-white font-medium py-3 rounded-lg flex items-center justify-center gap-2 transition-all">{isImporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}Processar com IA</button>
              </div>
            )}

            {activeTab === 'team' && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                 <h2 className="text-lg font-semibold text-white flex items-center gap-2 mb-6"><span className="w-1 h-6 bg-yellow-500 rounded-full"></span>Equipe</h2>
                 <div className="flex gap-2 items-end mb-6">
                    <Input label="Novo Vendedor" value={newSalespersonName} onChange={(e) => setNewSalespersonName(e.target.value)} />
                    <button onClick={handleAddSalesperson} className="bg-blue-600 p-3.5 rounded-lg"><Plus className="w-5 h-5" /></button>
                 </div>
                 <div className="space-y-2">
                    {salespeople.map(person => (
                      <div key={person} className="flex items-center justify-between bg-gray-800 p-3 rounded-lg border border-gray-700">
                         <span className="text-sm font-medium">{person}</span>
                         <button onClick={() => handleRemoveSalesperson(person)} className="text-gray-500 hover:text-red-400"><Trash2 className="w-4 h-4" /></button>
                      </div>
                    ))}
                 </div>
              </div>
            )}

            {activeTab === 'manual' && (
             <div className="space-y-6">
                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                  <h2 className="text-lg font-semibold text-white flex items-center gap-2 mb-6"><span className="w-1 h-6 bg-green-500 rounded-full"></span>Produtos</h2>
                  <div className="relative mb-4">
                    <Input label="Buscar Produto..." value={searchTerm} onChange={(e) => {setSearchTerm(e.target.value); setIsSearchOpen(true);}} onFocus={() => setIsSearchOpen(true)} icon={<Search className="w-4 h-4" />} />
                    {isSearchOpen && (
                        <div className="absolute z-20 w-full mt-1 bg-gray-800 border border-gray-700 rounded-lg shadow-xl max-h-60 overflow-y-auto">
                            {filteredProducts.map(product => (
                                <button key={product} className="w-full text-left px-4 py-3 text-sm hover:bg-gray-700 uppercase border-b border-gray-700/50 last:border-0" onClick={() => handleSearchSelect(product)}>{product}</button>
                            ))}
                        </div>
                    )}
                  </div>
                  <div className="grid grid-cols-2 gap-2 mb-4">
                    <Input label="Qtd" type="number" value={selectedQuantity} onChange={(e) => setSelectedQuantity(e.target.value)} />
                    <Input label="Valor (R$)" type="text" value={selectedPrice} readOnly className="bg-gray-800/50 text-gray-500" />
                  </div>
                  <button onClick={handleAddProduct} className="w-full bg-gray-700 hover:bg-gray-600 text-white text-sm font-semibold rounded-lg py-3 flex items-center justify-center gap-2">Adicionar</button>
                  <div className="space-y-2 mt-4">
                    {data.products.map((p, idx) => (
                      <div key={idx} className="bg-gray-800 p-3 rounded-lg border border-gray-700">
                        <div className="flex justify-between items-center mb-2">
                          <p className="text-sm truncate"><span className="text-gray-400 mr-1">{p.quantity}x</span> {p.name}</p>
                          <button onClick={() => handleRemoveProduct(idx)} className="text-gray-500 hover:text-red-400"><Trash2 className="w-4 h-4" /></button>
                        </div>
                        <div className="grid grid-cols-2 gap-2">
                          <input type="text" placeholder="Garantia" value={p.warrantyTime} onChange={(e) => handleUpdateProductWarranty(idx, 'time', e.target.value)} className="bg-gray-900 border border-gray-700 text-xs rounded px-2 py-1" />
                          <select value={p.warrantyUnit} onChange={(e) => handleUpdateProductWarranty(idx, 'unit', e.target.value)} className="bg-gray-900 border border-gray-700 text-xs rounded px-2 py-1">
                            <option value="DIAS">DIAS</option><option value="MESES">MESES</option><option value="ANOS">ANOS</option>
                          </select>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 shadow-xl">
                  <h2 className="text-lg font-semibold text-white flex items-center gap-2 mb-6"><span className="w-1 h-6 bg-blue-500 rounded-full"></span>Cliente</h2>
                  <div className="grid grid-cols-2 gap-4 mb-4">
                    <Input label="Cód. Venda" name="saleCode" value={data.saleCode} onChange={handleChange} />
                    <Select label="Vendedor" name="salesperson" value={data.salesperson} onChange={handleChange} options={salespeople} />
                  </div>
                  <Input label="Nome do Cliente" name="name" value={data.name} onChange={handleChange} className="mb-4" />
                  <Input label="Rua" name="street" value={data.street} onChange={handleChange} className="mb-4" />
                  <div className="grid grid-cols-2 gap-4 mb-4">
                    <Input label="Nº" name="number" value={data.number} onChange={handleChange} />
                    <Input label="Bairro" name="neighborhood" value={data.neighborhood} onChange={handleChange} />
                  </div>
                  <Input label="Cidade" name="city" value={data.city} onChange={handleChange} className="mb-4" />
                  <div className="grid grid-cols-2 gap-4">
                    <Input label="Contato 1" name="contact1" value={data.contact1} onChange={handleChange} />
                    <Input label="Contato 2" name="contact2" value={data.contact2} onChange={handleChange} />
                  </div>
                </div>
             </div>
            )}
          </div>

          <div className="lg:col-span-7 space-y-6">
            <div className="bg-gray-900 border border-gray-800 rounded-2xl p-4 shadow-xl flex flex-wrap gap-3 items-center justify-end">
              <button onClick={handleResetData} className="px-4 py-2 bg-red-600 rounded-lg text-sm font-medium">Novo Atendimento</button>
              <button onClick={() => generateReceiptPDF(getDataForExport())} className="px-4 py-2 bg-blue-600 rounded-lg text-sm font-medium">Gerar PDF</button>
            </div>

            <div className="bg-gray-900 border border-gray-800 rounded-2xl p-8 shadow-2xl relative overflow-hidden">
                <div className="bg-white text-gray-900 p-8 rounded-lg shadow-sm min-h-[600px] max-w-lg mx-auto flex flex-col">
                    <div className="bg-[#1e40af] text-white p-6 -mx-8 -mt-8 mb-6">
                        <h1 className="font-serif font-bold text-3xl">BelConfort</h1>
                        <span className="text-[9px] tracking-[0.2em]">CAMAS E MÓVEIS</span>
                    </div>
                    <div className="border border-gray-300 mb-6 text-sm p-2">
                        <p className="text-[8px] font-bold text-gray-400">CLIENTE</p>
                        <p className="text-xs mb-2">{data.name || '-'}</p>
                        <p className="text-[8px] font-bold text-gray-400">ENDEREÇO</p>
                        <p className="text-xs">{data.street ? `${data.street}, ${data.number}` : '-'}</p>
                    </div>
                    <div className="mb-4 flex-1">
                        <div className="grid grid-cols-[1fr_40px_80px] bg-gray-100 text-[9px] font-bold p-1 gap-2">
                            <div>DESCRIÇÃO</div><div className="text-center">QTD</div><div className="text-right">TOTAL</div>
                        </div>
                        {data.products.map((p, i) => (
                          <div key={i} className="grid grid-cols-[1fr_40px_80px] text-[10px] py-1 border-b border-gray-200 gap-2">
                            <div>{p.name}</div><div className="text-center">{p.quantity}</div><div className="text-right">{(p.price * p.quantity).toFixed(2)}</div>
                          </div>
                        ))}
                    </div>
                    <div className="border-t border-gray-300 pt-4 flex justify-between items-end">
                        <div className="text-[10px]">
                          <p><b>VENDEDOR:</b> {data.salesperson}</p>
                          <p><b>PAGAMENTO:</b> {data.paymentMethod}</p>
                        </div>
                        <div className="text-right">
                          <p className="text-xs text-gray-500">Subtotal: R$ {subtotal.toFixed(2)}</p>
                          <p className="text-lg font-bold text-blue-900">TOTAL: R$ {totalValue.toFixed(2)}</p>
                        </div>
                    </div>
                </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

