import { jsPDF } from 'jspdf';
import { ReceiptData } from '../types';
import QRCode from 'qrcode';

const COLORS = {
  primary: '#1e40af',
  secondary: '#1e293b',
  accent: '#3b82f6',
  border: '#cbd5e1',
  text: '#0f172a',
  lightText: '#64748b',
  white: '#ffffff',
  bg: '#f8fafc'
};

export const createPDFDoc = async (data: ReceiptData): Promise<jsPDF> => {
  const doc = new jsPDF();
  const pageWidth = 210;
  const margin = 20;
  const contentWidth = pageWidth - (margin * 2);
  let y = 20;

  doc.setFillColor(COLORS.primary);
  doc.rect(0, 0, pageWidth, 50, 'F');

  doc.setTextColor(COLORS.white);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(28);
  doc.text("BELCONFORT", margin, 30);

  doc.setFontSize(9);
  doc.setFont("helvetica", "normal");
  doc.text("ECOSISTEMA PREMIUM DE CONFORTO", margin, 36);

  doc.setFontSize(14);
  doc.setFont("helvetica", "bold");
  doc.text("COMPROVANTE DE PEDIDO", margin + contentWidth, 32, { align: 'right' });

  doc.setFontSize(10);
  doc.text(`CÓDIGO: ${data.saleCode || '---'}`, margin + contentWidth, 38, { align: 'right' });

  y = 65;
  doc.setTextColor(COLORS.text);
  doc.setFontSize(10);
  doc.text(`CLIENTE: ${data.name.toUpperCase() || '---'}`, margin, y);
  y += 6;
  doc.text(`ENDEREÇO: ${data.street || '---'}, ${data.number || '-'}`, margin, y);
  y += 15;

  doc.setFillColor(COLORS.secondary);
  doc.rect(margin, y, contentWidth, 10, 'F');
  doc.setTextColor(COLORS.white);
  doc.text("PRODUTO", margin + 5, y + 6.5);
  doc.text("TOTAL", margin + contentWidth - 5, y + 6.5, { align: 'right' });

  y += 12;
  doc.setTextColor(COLORS.text);
  let subtotal = 0;
  data.products.forEach(p => {
    const total = p.price * p.quantity;
    subtotal += total;
    doc.text(`${p.quantity}x ${p.name.toUpperCase()}`, margin + 5, y);
    doc.text(total.toFixed(2), margin + contentWidth - 5, y, { align: 'right' });
    y += 8;
  });

  const finalTotal = subtotal - (data.bundleDiscount || 0) - (data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100));

  y += 10;
  doc.setFont("helvetica", "bold");
  doc.text("TOTAL GERAL:", margin + contentWidth - 60, y);
  doc.text(`R$ ${Math.max(0, finalTotal).toFixed(2)}`, margin + contentWidth - 5, y, { align: 'right' });

  try {
    const qrDataUrl = await QRCode.toDataURL(`https://belconfort.com.br/${data.saleCode}`);
    doc.addImage(qrDataUrl, 'PNG', margin, 260, 25, 25);
  } catch (e) {}

  return doc;
};

export const generateReceiptPDF = async (data: ReceiptData) => {
  const doc = await createPDFDoc(data);
  doc.save(`BELCONFORT_${data.saleCode || 'PEDIDO'}.pdf`);
};

export const getReceiptBlob = async (data: ReceiptData): Promise<Blob> => {
  const doc = await createPDFDoc(data);
  return doc.output('blob');
};

import { GoogleGenAI, Type } from "@google/genai";
import { ReceiptData } from "../types";

export const generateClientMessage = async (data: ReceiptData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  const model = "gemini-3-flash-preview";

  const prompt = `
    Você é um assistente de vendas da BelConfort.
    Escreva uma mensagem amigável para WhatsApp confirmando o pedido de ${data.name}.
    Total: R$ ${data.products.reduce((acc, p) => acc + (p.price * p.quantity), 0).toFixed(2)}.
    Use emojis.
  `;

  try {
    const response = await ai.models.generateContent({ model, contents: prompt });
    return response.text || "Pedido confirmado!";
  } catch (error) {
    return "Pedido confirmado!";
  }
};

export const parseReceiptFromText = async (text: string, catalogNames: string[] = []): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  const model = "gemini-3-flash-preview";

  const prompt = `Extraia dados de cliente e itens (quantidade e nome) do texto: ${text}. Use estes nomes se possível: ${catalogNames.join(', ')}`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            clientData: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                street: { type: Type.STRING },
                number: { type: Type.STRING },
                neighborhood: { type: Type.STRING }
              }
            },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  quantity: { type: Type.NUMBER }
                }
              }
            }
          }
        }
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    throw error;
  }
};
